import {
  Component,
  h,
  Host,
  Element,
  Prop,
  Watch,
  Event,
  State,
  type ComponentInterface,
  type EventEmitter,
} from '@stencil/core';
import { Provide } from '@src/framework/runtime-context';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { SegmentedControlContext, type SegmentedControlContextValue } from './context';

const PREFIX = 'segmented-control';

/**
 * @slot default - Use the default slot to pass `ks-segmented-control-item` options.
 * @part base - The base part.
 */
@Component({
  tag: 'ks-segmented-control',
  styleUrl: 'styles/ks-segmented-control.scss',
  shadow: true,
})
export class KsSegmentedControl implements ComponentInterface {
  @Element() el!: HTMLKsSegmentedControlElement;

  @Provide({ context: SegmentedControlContext }) private context: SegmentedControlContextValue = {
    value: '',
    disabled: false,
  };

  /** Indicates whether the segmented group is disabled. When `true`, the user will not be able to interact with the segmented items. */
  @Prop() disabled = false;
  /** The selected value of the segmented control. This prop is controlled externally and will override the internal state. */
  @Prop() @Vue2ValueFix() value?: string | number;
  /** The default selected value of the segmented control by default. If not empty, it will be in selected state when first rendered. */
  @Prop() defaultValue: string | number = '';
  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() mergedValue?: string | number;

  /** Emits when the segment selector's selected state changes. The event carries a string indicating the new selected state. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<string | number>;

  @Watch('mergedValue')
  protected mergedValueWatcher(value: string | number) {
    this.context = {
      ...this.context,
      value,
    };
    sendActionTracking(this.el, { eventType: 'change', componentParams: { value } });
  }

  @Watch('disabled')
  protected disabledWatcher(disabled: boolean) {
    this.context = {
      ...this.context,
      disabled,
    };
  }

  constructor() {
    registerPluginManager(this.el);
  }

  componentWillLoad() {
    this.context = {
      disabled: this.disabled,
      value: this.mergedValue ?? '',
      updateValue: this.changeItemValue,
    };
  }

  private changeItemValue = (value: string | number) => {
    if (this.mergedValue === value) return;
    this.mergedValue = value;
  };

  render() {
    const { disabled } = this.context;

    return (
      <Host class="KsSegmentedControl">
        <div
          class={{
            [PREFIX]: true,
            [`${PREFIX}--disabled`]: disabled,
          }}
          role="group"
          part="base"
        >
          <slot />
        </div>
      </Host>
    );
  }
}
